import os
import sys
import modal

MAX_SIZE_BYTES = 100 * 1024 * 1024
OUTPUT_DIR = "modalfajlok"


def get_client():
    token_id = os.environ.get("MODAL_TOKEN_ID")
    token_secret = os.environ.get("MODAL_TOKEN_SECRET")
    if token_id and token_secret:
        return modal.Client.from_credentials(token_id, token_secret)
    return modal.Client.from_env()


def sanitize_path_component(name):
    return name.replace(":", "_").replace("\\", "_")


def get_entry_attribute(entry, attribute_name, default_value=None):
    return getattr(entry, attribute_name, default_value)


def is_file_entry(entry):
    entry_type = get_entry_attribute(entry, "type")
    file_entry_type = getattr(getattr(modal, "volume", None), "FileEntryType", None)
    if file_entry_type is not None:
        return entry_type == file_entry_type.FILE
    return not bool(get_entry_attribute(entry, "is_dir", False))


def download_volume_files(volume, client):
    volume_name = volume.name
    entries = volume.listdir("/", recursive=True)
    for entry in entries:
        if not is_file_entry(entry):
            continue
        file_size = get_entry_attribute(entry, "size", 0)
        if file_size >= MAX_SIZE_BYTES:
            continue
        remote_path = get_entry_attribute(entry, "path")
        if not remote_path:
            continue
        normalized_remote_path = remote_path.lstrip("/")
        local_path = os.path.join(
            OUTPUT_DIR,
            sanitize_path_component(volume_name),
            normalized_remote_path,
        )
        local_directory = os.path.dirname(local_path)
        os.makedirs(local_directory, exist_ok=True)
        with open(local_path, "wb") as local_file:
            for chunk in volume.read_file(remote_path):
                local_file.write(chunk)
        print(f"Downloaded: {volume_name}/{normalized_remote_path} ({file_size} bytes)")


def main():
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    client = get_client()
    volumes = modal.Volume.objects.list(client=client)
    if not volumes:
        print("No volumes found in this workspace.")
        return
    failed_volumes = []
    for volume in volumes:
        try:
            download_volume_files(volume, client)
        except Exception as error:
            failed_volumes.append((volume.name, str(error)))
            print(f"Failed to process volume {volume.name}: {error}", file=sys.stderr)
    if failed_volumes:
        raise RuntimeError(
            "One or more volumes could not be processed: "
            + "; ".join(f"{name}: {message}" for name, message in failed_volumes)
        )


if __name__ == "__main__":
    main()
